/* Generated by Payload, with two local changes: the admin renders per request
 * (see `connection()` below) and loads the site's fonts (Fraunces, Inter; Mukta for Hindi).
 * Keep both if Payload regenerates this file. */
import config from '@payload-config'
import '@payloadcms/next/css'
import type { ServerFunctionClient } from 'payload'
import { handleServerFunctions, RootLayout } from '@payloadcms/next/layouts'
import { Fraunces, Inter, Mukta } from 'next/font/google'
import { connection } from 'next/server'
import React from 'react'

import { importMap } from './admin/importMap.js'
import './custom.scss'

// The website's two faces, so the admin feels like part of the same trust.
const fraunces = Fraunces({ subsets: ['latin'], axes: ['opsz'], variable: '--font-fraunces', display: 'swap' })
const inter = Inter({ subsets: ['latin'], variable: '--font-inter', display: 'swap' })
const hindi = Mukta({
  subsets: ['devanagari'],
  weight: ['400'],
  variable: '--font-hindi',
  display: 'swap',
  preload: false,
})

type Args = {
  children: React.ReactNode
}

/**
 * The admin depends on who is signed in and reads the clock while rendering,
 * so it can't be prerendered under Cache Components. `instant = false` lets
 * this segment block (no static shell); `connection()` makes it request-time.
 * The public website keeps its static rendering — this is the /admin layout only.
 */
export const instant = false

const serverFunction: ServerFunctionClient = async function (args) {
  'use server'
  return handleServerFunctions({
    ...args,
    config,
    importMap,
  })
}

const Layout = async ({ children }: Args) => {
  await connection()
  return (
    <RootLayout
      config={config}
      htmlProps={{ className: `${fraunces.variable} ${inter.variable} ${hindi.variable}` }}
      importMap={importMap}
      serverFunction={serverFunction}
    >
      {children}
    </RootLayout>
  )
}

export default Layout
